package AIHelp;

import java.util.ArrayList;
import java.util.List;

/** Structured query plan generated by the AI layer. It is not SQL. */
public class AIQueryPlan {

    private List<String> tables = new ArrayList<>();
    private List<String> select = new ArrayList<>();
    private List<AIJoin> joins = new ArrayList<>();
    private List<AIFilter> filters = new ArrayList<>();
    private List<String> groupBy = new ArrayList<>();
    private AIOrderBy orderBy;
    private Integer limit;

    public List<String> getTables() {
        return tables;
    }

    public void setTables(List<String> tables) {
        this.tables = tables;
    }

    public List<String> getSelect() {
        return select;
    }

    public void setSelect(List<String> select) {
        this.select = select;
    }

    public List<AIJoin> getJoins() {
        return joins;
    }

    public void setJoins(List<AIJoin> joins) {
        this.joins = joins;
    }

    public List<AIFilter> getFilters() {
        return filters;
    }

    public void setFilters(List<AIFilter> filters) {
        this.filters = filters;
    }

    public List<String> getGroupBy() {
        return groupBy;
    }

    public void setGroupBy(List<String> groupBy) {
        this.groupBy = groupBy;
    }

    public AIOrderBy getOrderBy() {
        return orderBy;
    }

    public void setOrderBy(AIOrderBy orderBy) {
        this.orderBy = orderBy;
    }

    public Integer getLimit() {
        return limit;
    }

    public void setLimit(Integer limit) {
        this.limit = limit;
    }
}
